sparql_tries.sparql:
SELECT DISTINCT (STR(?y) AS ?modelYear)
WHERE {
  ?camp rc:campaignNumber "26V430000" ;
        rc:affects ?variant .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?y .
  ?model rc:name "TELLURIDE" ;
         rc:ofMake ?make .
  ?make rc:name "KIA" .
}
ORDER BY ?modelYear

SELECT DISTINCT ?catName WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber "10V388000" ;
            rc:affectsComponent ?comp .
  ?comp skos:broader* ?cat .
  FILTER NOT EXISTS { ?cat skos:broader ?parent }
  ?cat rc:name ?catName .
}
ORDER BY ?catName

SELECT ?date WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber "23V651000" ;
            rc:reportReceivedDate ?date .
}

SELECT ?potentiallyAffected WHERE {
  ?campaign rc:campaignNumber "26V430000" ;
            rc:potentiallyAffected ?potentiallyAffected .
}

SELECT DISTINCT ?campaignNo ?make
WHERE {
  ?c a rc:RecallCampaign ;
     rc:doNotDrive ?dnd ;
     rc:campaignNumber ?campaignNo ;
     rc:affects ?v .
  FILTER(?dnd = true)
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?make .
  FILTER(UCASE(?make) IN ("HYUNDAI", "KIA", "GENESIS"))
}
ORDER BY ?campaignNo ?make

SELECT DISTINCT ?campaignNumber WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:initiatedBy ?initiator ;
            rc:campaignNumber ?campaignNumber .
  FILTER(CONTAINS(UCASE(STR(?initiator)), "OVSC"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?date WHERE {
  ?camp rc:campaignNumber ?campaignNumber ;
        rc:reportReceivedDate ?date ;
        rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName ;
         rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(?makeName = "HYUNDAI" && ?modelName = "PALISADE")
  FILTER(YEAR(?date) = 2024)
}
ORDER BY ?date ?campaignNumber

SELECT ?compName (COUNT(DISTINCT ?c) AS ?campaigns) WHERE {
  ?comp rc:name ?compName ;
        skos:broader ?parent .
  ?c rc:affectsComponent ?comp ;
     rc:affects ?v .
  ?v rc:ofModel/rc:ofMake/rc:name ?mkName .
  FILTER(?mkName IN ('HYUNDAI', 'KIA'))
}
GROUP BY ?compName
HAVING (COUNT(DISTINCT ?mkName) = 2)
ORDER BY DESC(?campaigns)
LIMIT 1

SELECT DISTINCT ?campNo WHERE {
  ?camp a rc:RecallCampaign ;
        rc:campaignNumber ?campNo ;
        rc:affects ?v .
  ?v rc:modelYear ?year ;
     rc:ofModel ?m .
  ?m rc:name "SANTA FE" ;
     rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
  FILTER(STR(?year) = "2021")
}
ORDER BY ?campNo

SELECT DISTINCT ?genModelName WHERE {
  ?kiaCamp rc:affects ?kiaVar ;
           rc:affectsComponent ?comp .
  ?kiaVar rc:ofModel ?kiaModel .
  ?kiaModel rc:name "TELLURIDE" ;
            rc:ofMake ?kiaMake .
  ?kiaMake rc:name "KIA" .
  ?genCamp rc:affectsComponent ?comp ;
           rc:affects ?genVar .
  ?genVar rc:ofModel ?genModel .
  ?genModel rc:ofMake ?genMake ;
            rc:name ?genModelName .
  ?genMake rc:name "GENESIS" .
}
ORDER BY ?genModelName

SELECT ?modelName (COUNT(DISTINCT ?camp) AS ?campaignCount) WHERE {
  ?camp a rc:RecallCampaign ;
        rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName .
}
GROUP BY ?modelName
ORDER BY DESC(?campaignCount) ?modelName

SELECT (COUNT(DISTINCT ?camp) AS ?campaignCount) WHERE {
  ?camp a rc:RecallCampaign ;
        rc:reportReceivedDate ?date ;
        rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
  FILTER(YEAR(?date) = 2023)
}

SELECT ?topName (COUNT(DISTINCT ?model) AS ?modelCount) WHERE {
  ?camp a rc:RecallCampaign ;
        rc:affectsComponent ?comp ;
        rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?parent }
  ?top rc:name ?topName .
}
GROUP BY ?top ?topName
ORDER BY DESC(?modelCount) ?topName

SELECT ?campaignNo ?affected WHERE {
  ?c a rc:RecallCampaign ;
     rc:parkOutside true ;
     rc:campaignNumber ?campaignNo ;
     rc:potentiallyAffected ?affected .
}
ORDER BY DESC(?affected)

SELECT ?topName (COUNT(DISTINCT ?camp) AS ?campaigns) WHERE {
  ?make rc:name "GENESIS" .
  ?model rc:ofMake ?make .
  ?variant rc:ofModel ?model .
  ?camp rc:affects ?variant ;
        rc:affectsComponent ?comp .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?parent }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?campaigns)

SELECT (COUNT(DISTINCT ?year) AS ?yearCount) WHERE {
  ?make rc:name "HYUNDAI" .
  ?model rc:ofMake ?make ;
         rc:name "SONATA" .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?year .
  ?campaign rc:affects ?variant .
}

SELECT ?year (COUNT(DISTINCT ?c) AS ?reportCount) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mkName .
  FILTER(UCASE(STR(?mkName)) IN ("HYUNDAI", "KIA", "GENESIS"))
  BIND(YEAR(?d) AS ?year)
}
GROUP BY ?year
ORDER BY DESC(?reportCount) ?year

SELECT DISTINCT ?campaignNumber ?reportDate WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?c rc:reportReceivedDate ?reportDate . }
  OPTIONAL { ?c rc:defectSummary ?defect . }
  OPTIONAL { ?c rc:consequenceSummary ?conseq . }
  BIND(LCASE(CONCAT(COALESCE(STR(?defect), ""), " ", COALESCE(STR(?conseq), ""))) AS ?text)
  FILTER(CONTAINS(?text, "hydrogen"))
  FILTER(CONTAINS(?text, "leak") || CONTAINS(?text, "detect") || CONTAINS(?text, "sensor"))
}
ORDER BY ?reportDate

SELECT DISTINCT ?campaignNo WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNo .
  {
    ?c rc:affectsComponent ?comp .
    ?comp rc:name ?cn .
    FILTER(CONTAINS(UCASE(STR(?cn)), "CHARG"))
  }
  UNION
  {
    ?c rc:defectSummary ?ds .
    FILTER(CONTAINS(UCASE(STR(?ds)), "INTEGRATED CHARGING") || CONTAINS(UCASE(STR(?ds)), "ICCU"))
  }
}
ORDER BY ?campaignNo

SELECT DISTINCT ?campaignNumber WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:defectSummary ?defect }
  OPTIONAL { ?r rc:rootCause ?root }
  OPTIONAL { ?r rc:correctiveSummary ?corrective }
  OPTIONAL { ?r rc:affectsComponent/rc:name ?compName }
  BIND(CONCAT(COALESCE(?defect, ""), " ", COALESCE(?root, ""), " ", COALESCE(?corrective, ""), " ", COALESCE(?compName, "")) AS ?text)
  FILTER(REGEX(?text, "water|moisture|wet|humid|corrosion", "i"))
  FILTER(REGEX(?text, "trailer|tow|hitch", "i"))
  FILTER(REGEX(?text, "module|electronic|control|wiring|harness|connector|circuit", "i"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber WHERE {
  ?rc a rc:RecallCampaign ;
      rc:campaignNumber ?campaignNumber ;
      rc:defectSummary ?defect .
  FILTER(
    (CONTAINS(LCASE(?defect), "rod bearing") || (CONTAINS(LCASE(?defect), "connecting rod") && CONTAINS(LCASE(?defect), "bearing")))
    && CONTAINS(LCASE(?defect), "wear")
  )
}
ORDER BY ?campaignNumber
